const {
  emailValido,
  senhaValida,
  normalizarCpf,
  cpfValido,
  crmValido,
  calcularIdade,
  validarDataNascimento,
  exigeResponsavel,
  duracaoConsultaValida,
  UFS,
} = require('../../src/domain/validacoes');

describe('Validações de Domínio (validacoes.js)', () => {
  // --- RN01: E-mail ---
  /**
   * @caso CT-UNI-001
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RN01
   * @objetivo Aceitar e-mails com formato válido convencional
   * @resultadoEsperado emailValido retorna true para endereço válido
   */
  test('deve validar e-mail correto', () => {
    expect(emailValido('paciente@exemplo.com')).toBe(true);
    expect(emailValido('medico.clinica@sub.dominio.org')).toBe(true);
  });

  /**
   * @caso CT-UNI-002
   * @nivel unitario
   * @atributo confiabilidade
   * @subatributo maturidade
   * @requisito RN01
   * @objetivo Rejeitar e-mails sem arroba, sem domínio ou vazios
   * @resultadoEsperado emailValido retorna false para entradas malformadas
   */
  test('deve invalidar e-mail sem formato adequado', () => {
    expect(emailValido('')).toBe(false);
    expect(emailValido('semarroba.com')).toBe(false);
    expect(emailValido('usuario@')).toBe(false);
    expect(emailValido('@dominio.com')).toBe(false);
    expect(emailValido(null)).toBe(false);
  });

  // --- RN02: Senha ---
  /**
   * @caso CT-UNI-003
   * @nivel unitario
   * @atributo seguranca
   * @subatributo autenticidade
   * @requisito RN02
   * @objetivo Aceitar senha com 8 ou mais caracteres contendo letras e números
   * @resultadoEsperado senhaValida retorna true
   */
  test('deve validar senha forte com letras e números e 8 caracteres', () => {
    expect(senhaValida('Senha123')).toBe(true);
    expect(senhaValida('abc12345')).toBe(true);
  });

  /**
   * @caso CT-UNI-004
   * @nivel unitario
   * @atributo seguranca
   * @subatributo autenticidade
   * @requisito RN02
   * @objetivo Rejeitar senha com menos de 8 caracteres
   * @resultadoEsperado senhaValida retorna false para senha de 7 caracteres
   */
  test('deve rejeitar senha curta no valor-limite inferior', () => {
    expect(senhaValida('Abc1234')).toBe(false);
  });

  /**
   * @caso CT-UNI-005
   * @nivel unitario
   * @atributo seguranca
   * @subatributo autenticidade
   * @requisito RN02
   * @objetivo Rejeitar senha que contenha apenas letras ou apenas números
   * @resultadoEsperado senhaValida retorna false se faltar letra ou dígito
   */
  test('deve rejeitar senha sem dígitos ou sem letras', () => {
    expect(senhaValida('SomenteLetras')).toBe(false);
    expect(senhaValida('1234567890')).toBe(false);
  });

  // --- RN03: CPF ---
  /**
   * @caso CT-UNI-006
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RN03
   * @objetivo Normalizar CPF removendo caracteres não numéricos
   * @resultadoEsperado Retornar apenas os 11 dígitos numéricos
   */
  test('deve normalizar CPF formatado com pontos e traço', () => {
    expect(normalizarCpf('529.982.247-25')).toBe('52998224725');
    expect(normalizarCpf(null)).toBe('');
  });

  /**
   * @caso CT-UNI-007
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RN03
   * @objetivo Validar CPF autêntico com dígitos verificadores corretos
   * @resultadoEsperado cpfValido retorna true
   */
  test('deve validar CPF com dígitos verificadores corretos', () => {
    expect(cpfValido('52998224725')).toBe(true);
    expect(cpfValido('11144477735')).toBe(true);
  });

  /**
   * @caso CT-UNI-008
   * @nivel unitario
   * @atributo confiabilidade
   * @subatributo tolerancia-a-falhas
   * @requisito RN03
   * @objetivo Rejeitar CPF com todos os dígitos iguais
   * @resultadoEsperado cpfValido retorna false mesmo que matematicamente a soma batesse
   */
  test('deve rejeitar CPF composto por dígitos repetidos', () => {
    expect(cpfValido('11111111111')).toBe(false);
    expect(cpfValido('00000000000')).toBe(false);
  });

  /**
   * @caso CT-UNI-009
   * @nivel unitario
   * @atributo confiabilidade
   * @subatributo tolerancia-a-falhas
   * @requisito RN03
   * @objetivo Rejeitar CPF com dígito verificador incorreto ou tamanho inválido
   * @resultadoEsperado cpfValido retorna false
   */
  test('deve rejeitar CPF com DV incorreto ou tamanho diferente de 11', () => {
    expect(cpfValido('52998224726')).toBe(false);
    expect(cpfValido('123456789')).toBe(false);
  });

  // --- RN05: Idade e Data de Nascimento ---
  /**
   * @caso CT-UNI-010
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RN05
   * @objetivo Calcular a idade exata com base na data de nascimento e data de referência
   * @resultadoEsperado Retornar a idade completa considerando se o aniversário já ocorreu no ano
   */
  test('deve calcular idade considerando mês e dia do aniversário', () => {
    const ref = new Date(2026, 9, 19); // 19/10/2026
    const jaFez = new Date(1990, 4, 14); // 14/05/1990 -> 36 anos
    const aindaNaoFez = new Date(1990, 11, 25); // 25/12/1990 -> 35 anos
    expect(calcularIdade(jaFez, ref)).toBe(36);
    expect(calcularIdade(aindaNaoFez, ref)).toBe(35);
  });

  /**
   * @caso CT-UNI-011
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RN05
   * @objetivo Aceitar data de nascimento válida e passada dentro do limite de 130 anos
   * @resultadoEsperado validarDataNascimento retorna null
   */
  test('deve aceitar data de nascimento válida e recente', () => {
    const hoje = new Date(2026, 9, 19);
    expect(validarDataNascimento('1990-05-14', hoje)).toBeNull();
  });

  /**
   * @caso CT-UNI-012
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo pertinencia
   * @requisito RN05
   * @objetivo Rejeitar data de nascimento futura
   * @resultadoEsperado Retornar mensagem de que data de nascimento não pode ser futura
   */
  test('deve rejeitar data de nascimento posterior à data de hoje', () => {
    const hoje = new Date(2026, 9, 19);
    const erro = validarDataNascimento('2026-10-20', hoje);
    expect(erro).toMatch(/não pode ser futura/i);
  });

  /**
   * @caso CT-UNI-013
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo pertinencia
   * @requisito RN05
   * @objetivo Rejeitar data de nascimento indicando idade superior a 130 anos
   * @resultadoEsperado Retornar erro informando o limite de 130 anos
   */
  test('deve rejeitar data de nascimento para mais de 130 anos', () => {
    const hoje = new Date(2026, 9, 19);
    const erro = validarDataNascimento('1895-01-01', hoje);
    expect(erro).toMatch(/não pode ser superior a 130 anos/i);
  });

  /**
   * @caso CT-UNI-014
   * @nivel unitario
   * @atributo confiabilidade
   * @subatributo tolerancia-a-falhas
   * @requisito RN05
   * @objetivo Rejeitar formato de data inexistente ou inválido
   * @resultadoEsperado Retornar mensagem de data inválida
   */
  test('deve rejeitar formato de data incorreto', () => {
    const hoje = new Date(2026, 9, 19);
    expect(validarDataNascimento('data-invalida', hoje)).toMatch(/Data de nascimento inválida/i);
    expect(validarDataNascimento('2026-02-30', hoje)).toMatch(/Data de nascimento inválida/i);
  });

  // --- RN06: Responsável para menores de 18 anos ---
  /**
   * @caso CT-UNI-015
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo completude
   * @requisito RN06
   * @objetivo Exigir responsável legal para menor de 18 anos
   * @resultadoEsperado exigeResponsavel retorna true para menor de 18 anos
   */
  test('deve indicar exigência de responsável para menor de 18 anos', () => {
    const hoje = new Date(2026, 9, 19);
    const menor = new Date(2016, 9, 19); // 10 anos
    expect(exigeResponsavel(menor, hoje)).toBe(true);
  });

  /**
   * @caso CT-UNI-016
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo completude
   * @requisito RN06
   * @objetivo Não exigir responsável legal para maior de 18 anos
   * @resultadoEsperado exigeResponsavel retorna false para quem tem 18 anos ou mais
   */
  test('não deve exigir responsável para quem tem exatamente 18 anos ou mais', () => {
    const hoje = new Date(2026, 9, 19);
    const exatamente18 = new Date(2008, 9, 19); // exatamente 18 anos
    const maior = new Date(2000, 1, 1);
    expect(exigeResponsavel(exatamente18, hoje)).toBe(false);
    expect(exigeResponsavel(maior, hoje)).toBe(false);
  });

  // --- RN07: CRM ---
  /**
   * @caso CT-UNI-017
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RN07
   * @objetivo Validar CRM no formato de 4 a 6 dígitos com barra e UF válida
   * @resultadoEsperado crmValido retorna true
   */
  test('deve validar CRM com formato e UF brasileira válida', () => {
    expect(crmValido('1234/SP')).toBe(true);
    expect(crmValido('12345/MG')).toBe(true);
    expect(crmValido('123456/RJ')).toBe(true);
  });

  /**
   * @caso CT-UNI-018
   * @nivel unitario
   * @atributo confiabilidade
   * @subatributo tolerancia-a-falhas
   * @requisito RN07
   * @objetivo Rejeitar CRM com dígitos insuficientes ou excessivos
   * @resultadoEsperado crmValido retorna false para menos de 4 ou mais de 6 dígitos
   */
  test('deve rejeitar CRM com quantidade de dígitos fora do intervalo 4-6', () => {
    expect(crmValido('123/SP')).toBe(false);
    expect(crmValido('1234567/SP')).toBe(false);
  });

  /**
   * @caso CT-UNI-019
   * @nivel unitario
   * @atributo confiabilidade
   * @subatributo tolerancia-a-falhas
   * @requisito RN07
   * @objetivo Rejeitar CRM com sigla de estado inexistente ou sem barra
   * @resultadoEsperado crmValido retorna false
   */
  test('deve rejeitar CRM com UF inválida ou sem separador', () => {
    expect(crmValido('123456/XX')).toBe(false);
    expect(crmValido('123456-SP')).toBe(false);
    expect(crmValido('123456')).toBe(false);
  });

  // --- RN08: Duração de Consulta ---
  /**
   * @caso CT-UNI-020
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RN08
   * @objetivo Aceitar durações válidas (15, 30, 45, 60 minutos)
   * @resultadoEsperado duracaoConsultaValida retorna true
   */
  test('deve aceitar durações de consulta válidas múltiplas de 15 entre 15 e 60', () => {
    expect(duracaoConsultaValida(15)).toBe(true);
    expect(duracaoConsultaValida(30)).toBe(true);
    expect(duracaoConsultaValida(45)).toBe(true);
    expect(duracaoConsultaValida(60)).toBe(true);
  });

  /**
   * @caso CT-UNI-021
   * @nivel unitario
   * @atributo confiabilidade
   * @subatributo tolerancia-a-falhas
   * @requisito RN08
   * @objetivo Rejeitar durações menores que 15, maiores que 60 ou não múltiplas de 15
   * @resultadoEsperado duracaoConsultaValida retorna false
   */
  test('deve rejeitar durações fora dos limites ou não múltiplas de 15', () => {
    expect(duracaoConsultaValida(0)).toBe(false);
    expect(duracaoConsultaValida(10)).toBe(false);
    expect(duracaoConsultaValida(20)).toBe(false);
    expect(duracaoConsultaValida(75)).toBe(false);
    expect(duracaoConsultaValida(null)).toBe(false);
  });

  // --- RNF07: Manutenibilidade e Isolamento ---
  /**
   * @caso CT-UNI-022
   * @nivel unitario
   * @atributo manutenibilidade
   * @subatributo modularidade
   * @requisito RNF07
   * @objetivo Garantir que UFS contém todas as 27 unidades federativas brasileiras
   * @resultadoEsperado UFS possui 27 elementos incluindo estados e DF
   */
  test('deve conter as 27 UFs válidas brasileiras', () => {
    expect(UFS).toHaveLength(27);
    expect(UFS).toContain('SP');
    expect(UFS).toContain('DF');
    expect(UFS).toContain('AM');
  });
});

backend/__testes__/integracao/cadastro-s.source:
const { abrirBanco } = require('../../src/db/connection');
const { criarServicos } = require('../../src/services');
const clock = require('../../src/utils/clock');

describe('Integração: CadastroService', () => {
  let db;
  let servicos;
  const agoraFixo = new Date('2026-10-19T08:00:00');

  beforeEach(() => {
    clock.definirAgora(agoraFixo);
    db = abrirBanco(':memory:');
    servicos = criarServicos(db);
  });

  afterEach(() => {
    clock.definirAgora(null);
    db.close();
  });

  /**
   * @caso CT-INT-010
   * @nivel integracao
   * @atributo adequacao-funcional
   * @subatributo completude
   * @requisito RF02.1, RF02.3, RN03
   * @objetivo Cadastrar paciente com sucesso persistindo usuário e paciente em transação
   * @resultadoEsperado Paciente criado com CPF gravado somente em dígitos e senha em hash
   */
  test('deve registrar paciente completo persistindo nas tabelas usuarios e pacientes', () => {
    const dados = {
      nome: 'Mariana Silva',
      email: 'mariana@email.com',
      senha: 'SenhaForte123',
      cpf: '529.982.247-25',
      dataNascimento: '1995-04-12',
      telefone: '(11) 98765-4321',
    };

    const paciente = servicos.cadastroService.registrarPaciente(dados);
    expect(paciente.id).toBeDefined();
    expect(paciente.nome).toBe('Mariana Silva');
    expect(paciente.cpf).toBe('52998224725'); // apenas dígitos
    expect(paciente.email).toBe('mariana@email.com');

    // Verifica que usuário foi inserido
    const usuario = servicos.repos.usuarios.buscarPorEmail('mariana@email.com');
    expect(usuario).toBeDefined();
    expect(usuario.perfil).toBe('PACIENTE');
  });

  /**
   * @caso CT-INT-011
   * @nivel integracao
   * @atributo adequacao-funcional
   * @subatributo pertinencia
   * @requisito RN01
   * @objetivo Rejeitar cadastro com e-mail já existente
   * @resultadoEsperado Lança erro CONFLITO informando e-mail já cadastrado
   */
  test('deve rejeitar cadastro de paciente com e-mail duplicado', () => {
    const dados1 = {
      nome: 'Primeiro Paciente',
      email: 'duplicado@email.com',
      senha: 'Senha123',
      cpf: '529.982.247-25',
      dataNascimento: '1990-01-01',
    };
    servicos.cadastroService.registrarPaciente(dados1);

    const dados2 = {
      nome: 'Segundo Paciente',
      email: 'duplicado@email.com',
      senha: 'Senha123',
      cpf: '111.444.777-35',
      dataNascimento: '1992-02-02',
    };
    expect(() => servicos.cadastroService.registrarPaciente(dados2)).toThrow(/E-mail já cadastrado/i);
  });

  /**
   * @caso CT-INT-012
   * @nivel integracao
   * @atributo adequacao-funcional
   * @subatributo pertinencia
   * @requisito RN03
   * @objetivo Rejeitar cadastro de paciente com CPF já registrado
   * @resultadoEsperado Lança erro CONFLITO de CPF
   */
  test('deve rejeitar cadastro com CPF duplicado', () => {
    servicos.cadastroService.registrarPaciente({
      nome: 'Pessoa Um',
      email: 'um@email.com',
      senha: 'Senha123',
      cpf: '529.982.247-25',
      dataNascimento: '1990-01-01',
    });

    expect(() => servicos.cadastroService.registrarPaciente({
      nome: 'Pessoa Dois',
      email: 'dois@email.com',
      senha: 'Senha123',
      cpf: '529.982.247-25',
      dataNascimento: '1992-02-02',
    })).toThrow(/CPF já cadastrado/i);
  });

  /**
   * @caso CT-INT-013
   * @nivel integracao
   * @atributo adequacao-funcional
   * @subatributo pertinencia
   * @requisito RN06
   * @objetivo Exigir nome do responsável para paciente menor de 18 anos
   * @resultadoEsperado Lança erro VALIDACAO se responsavelNome não for informado
   */
  test('deve exigir responsável para menor de 18 anos no cadastro de paciente', () => {
    // 10 anos em 2026 -> 2016
    expect(() => servicos.cadastroService.registrarPaciente({
      nome: 'Criança Silva',
      email: 'crianca@email.com',
      senha: 'Senha123',
      cpf: '390.533.447-05',
      dataNascimento: '2016-05-10',
    })).toThrow(/deve informar o nome do responsável/i);

    // Com responsável
    const paciente = servicos.cadastroService.registrarPaciente({
      nome: 'Criança Silva',
      email: 'crianca@email.com',
      senha: 'Senha123',
      cpf: '390.533.447-05',
      dataNascimento: '2016-05-10',
      responsavelNome: 'Mãe Silva',
    });
    expect(paciente.responsavelNome).toBe('Mãe Silva');
  });

  /**
   * @caso CT-INT-014
   * @nivel integracao
   * @atributo adequacao-funcional
   * @subatributo completude
   * @requisito RF03.1, RN09
   * @objetivo Cadastrar especialidade com preço base em centavos
   * @resultadoEsperado Especialidade cadastrada e recuperável com id gerado
   */
  test('deve cadastrar especialidade com nome e preço base', () => {
    const esp = servicos.cadastroService.criarEspecialidade({
      nome: 'Ortopedia',
      precoCentavos: 28000,
    });
    expect(esp.id).toBeDefined();
    expect(esp.nome).toBe('Ortopedia');
    expect(esp.precoCentavos).toBe(28000);
  });

  /**
   * @caso CT-INT-015
   * @nivel integracao
   * @atributo adequacao-funcional
   * @subatributo pertinencia
   * @requisito RN09
   * @objetivo Impedir criação de especialidade com nome duplicado ou preço menor/igual a zero
   * @resultadoEsperado Lança erro apropriado de conflito ou validação
   */
  test('deve rejeitar especialidade com preço não positivo ou nome duplicado', () => {
    expect(() => servicos.cadastroService.criarEspecialidade({
      nome: 'Fisioterapia',
      precoCentavos: 0,
    })).toThrow(/maior que zero/i);

    servicos.cadastroService.criarEspecialidade({ nome: 'Fisioterapia', precoCentavos: 12000 });
    expect(() => servicos.cadastroService.criarEspecialidade({
      nome: 'Fisioterapia',
      precoCentavos: 15000,
    })).toThrow(/já cadastrada/i);
  });

  /**
   * @caso CT-INT-016
   * @nivel integracao
   * @atributo adequacao-funcional
   * @subatributo completude
   * @requisito RF04.1, RN07, RN08
   * @objetivo Cadastrar médico com especialidade e duração de consulta
   * @resultadoEsperado Médico persistido vinculado ao usuário com perfil MEDICO
   */
  test('deve cadastrar médico associado a uma especialidade existente', () => {
    const esp = servicos.cadastroService.criarEspecialidade({ nome: 'Neurologia', precoCentavos: 35000 });
    const medico = servicos.cadastroService.criarMedico({
      nome: 'Dr. Roberto',
      email: 'roberto@clinica.com',
      senha: 'Senha123',
      crm: '554433/SP',
      especialidadeId: esp.id,
      duracaoConsultaMin: 45,
    });

    expect(medico.id).toBeDefined();
    expect(medico.crm).toBe('554433/SP');
    expect(medico.duracaoConsultaMin).toBe(45);
    expect(medico.especialidadeId).toBe(esp.id);
  });

  /**
   * @caso CT-INT-017
   * @nivel integracao
   * @atributo confiabilidade
   * @subatributo tolerancia-a-falhas
   * @requisito RF04.1, RN07
   * @objetivo Rejeitar cadastro de médico com CRM duplicado ou especialidade inexistente
   * @resultadoEsperado Lança erro de conflito de CRM ou validação de especialidade
   */
  test('deve rejeitar médico com especialidade inexistente ou CRM repetido', () => {
    const esp = servicos.cadastroService.criarEspecialidade({ nome: 'Oftalmologia', precoCentavos: 20000 });
    servicos.cadastroService.criarMedico({
      nome: 'Dra. Julia',
      email: 'julia@clinica.com',
      senha: 'Senha123',
      crm: '998877/RJ',
      especialidadeId: esp.id,
      duracaoConsultaMin: 30,
    });

    // CRM repetido
    expect(() => servicos.cadastroService.criarMedico({
      nome: 'Dr. Marcos',
      email: 'marcos@clinica.com',
      senha: 'Senha123',
      crm: '998877/RJ',
      especialidadeId: esp.id,
    })).toThrow(/CRM já cadastrado/i);

    // Especialidade inexistente
    expect(() => servicos.cadastroService.criarMedico({
      nome: 'Dr. Marcos',
      email: 'marcos@clinica.com',
      senha: 'Senha123',
      crm: '112233/RJ',
      especialidadeId: 9999,
    })).toThrow(/Especialidade inexistente/i);
  });

  /**
   * @caso CT-INT-018
   * @nivel integracao
   * @atributo adequacao-funcional
   * @subatributo pertinencia
   * @requisito RN21
   * @objetivo Ativar e inativar usuário no sistema
   * @resultadoEsperado Flag ativo atualizada para false e true conforme solicitado
   */
  test.skip('deve ativar e inativar usuário', () => {
    const esp = servicos.cadastroService.criarEspecialidade({ nome: 'Ginecologia', precoCentavos: 22000 });
    const medico = servicos.cadastroService.criarMedico({
      nome: 'Dra. Laura',
      email: 'laura@clinica.com',
      senha: 'Senha123',
      crm: '334455/SP',
      especialidadeId: esp.id,
    });

    servicos.cadastroService.definirUsuarioAtivo(medico.usuarioId, false);
    let u = servicos.repos.usuarios.buscarPorId(medico.usuarioId);
    expect(u.ativo).toBe(0);

    servicos.cadastroService.definirUsuarioAtivo(medico.usuarioId, true);
    u = servicos.repos.usuarios.buscarPorId(medico.usuarioId);
    expect(u.ativo).toBe(1);
  });

  /**
   * @caso CT-INT-019
   * @nivel integracao
   * @atributo seguranca
   * @subatributo integridade
   * @requisito RNF03
   * @objetivo Garantir segurança contra injeção SQL no cadastro
   * @resultadoEsperado Trata strings com aspas e comandos SQL como literais sem quebrar o banco
   */
  test('deve persistir dados com caracteres especiais sem vulnerabilidade a SQL injection', () => {
    const esp = servicos.cadastroService.criarEspecialidade({
      nome: "Especialidade' OR '1'='1",
      precoCentavos: 10000,
    });
    expect(esp.nome).toBe("Especialidade' OR '1'='1");
    const buscada = servicos.repos.especialidades.buscarPorId(esp.id);
    expect(buscada.nome).toBe("Especialidade' OR '1'='1");
  });

  /**
   * @caso CT-INT-020
   * @nivel integracao
   * @atributo confiabilidade
   * @subatributo recuperabilidade
   * @requisito RNF04
   * @objetivo Rollback automático de transação caso ocorra falha ao inserir paciente
   * @resultadoEsperado Nenhum usuário órfão é deixado no banco se a criação de paciente falhar
   */
  test.skip('deve reverter inserção de usuário se a transação do paciente falhar', () => {
    const totalUsuariosAntes = db.prepare('SELECT COUNT(*) AS n FROM usuarios').get().n;

    // Força falha com CPF que passa no formato mas duplicado ou erro de banco
    try {
      servicos.cadastroService.registrarPaciente({
        nome: 'Paciente Teste',
        email: 'teste.falha@email.com',
        senha: 'Senha123',
        cpf: '529.982.247-25',
        dataNascimento: '1990-01-01',
      });
    } catch {}

    // Tentativa com mesmo e-mail ou erro
    try {
      servicos.cadastroService.registrarPaciente({
        nome: 'Paciente Teste',
        email: 'outro@email.com',
        senha: 'Senha123',
        cpf: '529.982.247-25', // CPF duplicado disparado após usuário
        dataNascimento: '1990-01-01',
      });
    } catch {}

    const usuarioOrfao = servicos.repos.usuarios.buscarPorEmail('outro@email.com');
    expect(usuarioOrfao).toBeUndefined();
  });
});

